import{_ as a,o as t,c as o,a3 as i}from"./chunks/framework.BiZN3XWs.js";const u=JSON.parse('{"title":"Frank Backend Daemon Topology","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/backend-topology.md","filePath":"architecture/backend-topology.md","lastUpdated":1791339908000}'),s={name:"architecture/backend-topology.md"};function n(r,e,d,l,c,p){return t(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="frank-backend-daemon-topology" tabindex="-1">Frank Backend Daemon Topology <a class="header-anchor" href="#frank-backend-daemon-topology" aria-label="Permalink to &quot;Frank Backend Daemon Topology&quot;">​</a></h1><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><a href="/docs/protocol/cashweb-spec"><code>CASHWEB-PROTOCOL-SPEC.md</code></a> supersedes this document for human protocol semantics and wire allocation. The protobuf, route, record and exact-wire sketches below are historical transition inputs and are non-wire; they MUST NOT be implemented as target formats. The service ownership, storage separation and public/private reachability constraints remain required topology inputs subordinate to that specification.</p></div><p>Status: Owner-approved direction for #87, refined by <code>public-federation-plan.md</code>. Individual wire, storage, and route migrations remain staged behind their implementation tickets.</p><hr><h2 id="_1-architectural-goals" tabindex="-1">1. Architectural Goals <a class="header-anchor" href="#_1-architectural-goals" aria-label="Permalink to &quot;1. Architectural Goals&quot;">​</a></h2><ul><li>Keep one operator-facing <code>cashwebd</code> binary.</li><li>Federate compact public address-directory records, relay descriptors, and public pubsub records over the small-world peer graph.</li><li>Keep full signed presentation profiles on the user&#39;s selected relay while allowing verified fetches and caches.</li><li>Keep direct-message mailbox records inside the responsible operator&#39;s private cluster.</li><li>Make it structurally difficult for a future replication feature to gossip mailbox ciphertext, delivery metadata, or payment-attempt state.</li><li>Let an operator enable only the subsystems they intend to host.</li></ul><p>One binary does not imply one replication domain. The process composes four services with separate storage facades and route groups:</p><ol><li><strong><code>Directory</code></strong>: compact signed account-to-relay bindings, relay descriptors, rotation/revocation state, and directory admission policy.</li><li><strong><code>Profiles</code></strong>: full signed display names, biographies, avatars, application capabilities, and curated defaults stored on the selected relay. Profiles are publicly fetchable but not public gossip records.</li><li><strong><code>Pubsub</code></strong>: Monad-native public topic posts, votes, discovery indexes, and future topic events. The Lotus broadcast/topic subsystem is deprecated and is not an input to the new federation.</li><li><strong><code>Mailbox</code></strong>: inbox/outbox records, exact stamp-payment attempts, delivery jobs, tombstones, and client notification state.</li></ol><p>Node-local peer health, retry timers, and migration bookkeeping form a fifth operational class; they are not application records and are never federated.</p><hr><h2 id="_2-durable-data-classification" tabindex="-1">2. Durable-Data Classification <a class="header-anchor" href="#_2-durable-data-classification" aria-label="Permalink to &quot;2. Durable-Data Classification&quot;">​</a></h2><table tabindex="0"><thead><tr><th>RocksDB column family</th><th>Class</th><th>Public peer replication</th></tr></thead><tbody><tr><td><code>metadata</code>, <code>pkh_by_time</code></td><td>public address directory (legacy Lotus)</td><td>allowed</td></tr><tr><td><code>monad_profiles</code>, <code>monad_profiles_by_time</code>, <code>monad_profiles_by_name</code></td><td>relay-local presentation profile</td><td>forbidden</td></tr><tr><td><code>topic_messages</code>, <code>message_payloads</code>, <code>topic_burn_txs</code></td><td>deprecated Lotus broadcasts</td><td>forbidden</td></tr><tr><td><code>monad_topic_posts</code>, <code>monad_topic_posts_by_topic</code>, <code>monad_topic_discovery</code>, <code>monad_topic_votes</code></td><td>public pubsub</td><td>allowed</td></tr><tr><td><code>monad_messages</code>, <code>monad_messages_by_time</code></td><td>private mailbox</td><td>forbidden</td></tr><tr><td><code>monad_message_attempts</code></td><td>private mailbox/payment state</td><td>forbidden</td></tr><tr><td>future outbox, delivery-job, tombstone, and notification column families</td><td>private mailbox</td><td>forbidden</td></tr><tr><td>future address-directory and relay-descriptor families</td><td>public directory</td><td>allowed through an explicit facade</td></tr><tr><td>future peer health, crawl frontier, schema version, and migration journal</td><td>node-local operational</td><td>forbidden</td></tr></tbody></table><p>The security boundary is enforced by typed store facades and explicit replication allowlists, not by giving federation code a generic <code>Db</code> handle. Separate database paths remain a later deployment option; the logical ownership boundary must exist first so that split does not require redesigning records.</p><hr><h2 id="_3-replication-boundaries" tabindex="-1">3. Replication Boundaries <a class="header-anchor" href="#_3-replication-boundaries" aria-label="Permalink to &quot;3. Replication Boundaries&quot;">​</a></h2><p>Public federation receives only <code>Directory</code> and <code>Pubsub</code> interfaces. It may enumerate and apply signed public records, but it cannot import the presentation-profile or mailbox store modules or access a generic column-family iterator. Every replicated record carries a network tag and protocol version, and is validated as if received from an untrusted client before insertion.</p><p>The Monad profile store is not a temporary directory implementation: it contains display name, bio, avatar, and search data that the original system kept on the selected relay. Federation must wait for the dedicated directory schema rather than copying these full records as an intermediate compatibility measure.</p><p>Mailbox replication, if enabled for an operator&#39;s private cluster, is a different interface, configuration block, and authentication domain. Public peer discovery must never return private cluster endpoints or credentials. A single-node operator is valid and is the default.</p><hr><h2 id="_4-canonical-http-namespace" tabindex="-1">4. Canonical HTTP Namespace <a class="header-anchor" href="#_4-canonical-http-namespace" aria-label="Permalink to &quot;4. Canonical HTTP Namespace&quot;">​</a></h2><p>The canonical Monad API puts the network first and the replication domain second:</p><table tabindex="0"><thead><tr><th>Domain</th><th>Canonical routes</th></tr></thead><tbody><tr><td>Directory</td><td><code>/directory</code>, <code>/directory/:network/:address</code>, <code>/directory/relays/:node_id</code></td></tr><tr><td>Profiles</td><td><code>/profiles/:network/:address</code>, <code>/profiles/search</code>, <code>/profiles/curated-defaults</code></td></tr><tr><td>Mailbox</td><td><code>/monad/mailbox/inbox</code>, <code>/monad/mailbox/outbox</code>, <code>/monad/mailbox/sync</code>, <code>/monad/mailbox/events</code></td></tr><tr><td>Pubsub</td><td><code>/monad/pubsub/topics</code>, <code>/monad/pubsub/posts</code>, <code>/monad/pubsub/posts/:payload_hash</code>, <code>/monad/pubsub/votes</code>, <code>/monad/pubsub/events</code></td></tr></tbody></table><p>Future store-and-forward and deletion routes extend the mailbox domain rather than creating another top-level convention, for example <code>/monad/mailbox/deliveries</code> and <code>/monad/mailbox/tombstones</code>. Peer discovery and public catch-up live under <code>/v1/federation/...</code>.</p><p><code>/monad/mailbox/sync?cursor=&lt;opaque&gt;</code> is the single authoritative, mailbox-scoped change journal. <code>/monad/mailbox/events</code> is a live wake-up channel carrying the newest cursor; after a disconnect the client always recovers through <code>sync</code>.</p><hr><h2 id="_5-configuration-and-process-lifecycle" tabindex="-1">5. Configuration and Process Lifecycle <a class="header-anchor" href="#_5-configuration-and-process-lifecycle" aria-label="Permalink to &quot;5. Configuration and Process Lifecycle&quot;">​</a></h2><p><code>cashwebd</code> owns one listener and independently configurable route groups:</p><div class="language-toml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">profiles = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pubsub = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mailbox = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lotus_compat = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">federation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">enabled = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">seeds = []</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mailbox_cluster</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">enabled = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>The process starts in this order:</p><ol><li>Open RocksDB and complete schema migrations;</li><li>Construct the typed directory, profile, pubsub, mailbox, and node-local stores;</li><li>Construct enabled route groups;</li><li>Start private mailbox-cluster workers, if configured;</li><li>Start public federation discovery/catch-up, if configured;</li><li>Accept traffic only after required local recovery is complete.</li></ol><p>Shutdown stops accepting writes, drains or checkpoints local delivery jobs, stops federation, and then closes RocksDB.</p>`,31)])])}const b=a(s,[["render",n]]);export{u as __pageData,b as default};
